import os
import pdb

import numpy as np
from torch.utils import data
import torch

import random

from lib.utils.helpers.image_helper import ImageHelper
from lib.extensions.parallel.data_container import DataContainer
from lib.utils.tools.logger import Logger as Log

from PIL import Image
import cv2



class TestLoader(data.Dataset):
    def __init__(self, root_dir, dataset=None,
                 img_transform=None): 

        self.img_transform = img_transform

        self.img_list, self.name_list = self.__list_dirs(root_dir, dataset)

        size_mode = "fix_size"

        self.is_stack = size_mode != 'diverse_size'

        # self.label_list = []

    def __len__(self):
        return len(self.img_list)

    def __getitem__(self, index):
        ''' 
        load one image
        '''
        img = ImageHelper.read_image(self.img_list[index],
                                     tool='cv2',
                                     mode='BGR')

        ori_img_size = ImageHelper.get_size(img)

        h, w = img.shape[0], img.shape[1]

        if w > h:
            transFlag = True    # w > h
        else: 
            transFlag = False   # h >= w

        stdimg = np.zeros((400, 300, 3)).astype(np.uint8)

        
        # rotation
        if transFlag:
            img = cv2.rotate(img, 0)
            
        # padding
        h,w,c = img.shape
        if float(h/w) > 4/3.:
            img = cv2.resize(img, (int(400.*w/h), 400))###################################<----
            stdimg[:, :int(400.*w/h), :] = img    
        else:
            img = cv2.resize(img, (300, int(300.*h/w)))###################################<----    
            stdimg[:int(300.*h/w), :, :] = img       


        img_size = ImageHelper.get_size(img)
        border_size = ImageHelper.get_size(stdimg)

        if self.img_transform is not None:
            img = self.img_transform(stdimg)       


        meta = dict(
            img_size=img_size,
            border_size=border_size,
            ori_img_size=ori_img_size,
        )
        return dict(
            img=DataContainer(img, stack=self.is_stack),            
            meta=DataContainer(meta, stack=False, cpu_only=True),
            name=DataContainer(self.name_list[index], stack=False, cpu_only=True),
            imgname=DataContainer(self.img_list[index], stack=False, cpu_only=True)
        )



    def __list_dirs(self, root_dir, dataset):
        img_list = list()
        name_list = list()
        
        if len(dataset):
            image_dir = os.path.join(root_dir, dataset) # image_dir = os.path.join(root_dir, dataset, 'image')
        else:
            image_dir = root_dir

     
        imgfiles = sorted(os.listdir(image_dir))
        img_extension_dict = dict([['.'.join(n.split('.')[:-1]), n.split('.')[-1]] for n in imgfiles]) # searching ext by file name
        # img_extension = os.listdir(image_dir)[0].split('.')[-1] # same and fixed extension


        # directly input the file list name 
        file_list_txt = os.environ.get('use_file_list') # a file containing all the image names

        if file_list_txt is None:
            files = sorted(os.listdir(image_dir))
        else:
            Log.info("Using file list {} for training".format(file_list_txt))
            with open(os.path.join(root_dir, dataset, 'file_list', file_list_txt)) as f:
                files = [x.strip() for x in f]

        for file_name in files:
            image_name = '.'.join(file_name.split('.')[:-1])
            img_path = os.path.join(image_dir, '{}.{}'.format(image_name, img_extension_dict[image_name]))
           
            # print(img_path, label_path, keypoint_path)

            if not os.path.exists(img_path):
                Log.error('Path pair not exists: {}'.format(img_path))
                continue

            img_list.append(img_path)
        
            name_list.append(image_name)


        
        return img_list, name_list





